import React from 'react';
import { createRoot } from 'react-dom/client';
import StudentsSection from '../../src/components/dashboard/StudentsSection';
import RegistrationRequestsSection from '../../src/components/dashboard/RegistrationRequestsSection';
import { Toaster } from '../../src/components/ui/toaster';
import '../../src/index.css';
if (!import.meta.env.DEV || !['localhost', '127.0.0.1'].includes(location.hostname)) throw new Error('Local only');
localStorage.setItem('wajeh_role', 'manager');
localStorage.setItem('wajeh_account_id', '999');
const Component = location.search.includes('registration') ? RegistrationRequestsSection : StudentsSection;
createRoot(document.getElementById('root')).render(<main className="p-4 [font-family:var(--font-ui)]"><Component /><Toaster /></main>);
